param(
  [string]$ProjectRoot = "D:\simras-digital-twin-repository\simras-digital-twin"
)

$ErrorActionPreference = "Stop"
Set-Location $ProjectRoot
[Environment]::CurrentDirectory = (Get-Location).Path

$stamp = Get-Date -Format "yyyyMMdd_HHmmss"
$backup = Join-Path $ProjectRoot "archive\gis_real_data_fix_$stamp"
New-Item -ItemType Directory -Force $backup | Out-Null

Write-Host "`n============================================================" -ForegroundColor Cyan
Write-Host "SIMRAS GIS REAL-DATA REPAIR" -ForegroundColor Cyan
Write-Host "============================================================" -ForegroundColor Cyan

foreach ($file in @(
  ".\frontend\src\pages\gis\GISPage.tsx",
  ".\frontend\src\components\gis\GISMap.tsx"
)) {
  if (Test-Path $file) {
    Copy-Item $file (Join-Path $backup (Split-Path $file -Leaf)) -Force
  }
}

[IO.File]::WriteAllBytes(
  ".\frontend\src\pages\gis\GISPage.tsx",
  [Convert]::FromBase64String("")
)

[IO.File]::WriteAllBytes(
  ".\frontend\src\components\gis\GISMap.tsx",
  [Convert]::FromBase64String("")
)

Write-Host "GISPage + GISMap replaced with real-data versions." -ForegroundColor Green
Write-Host "Backup: $backup" -ForegroundColor DarkGray

Write-Host "`n=== BACKEND GIS ENDPOINT CHECK ===" -ForegroundColor Cyan

$endpoints = @(
  "http://localhost:8000/api/v1/gis/assets?limit=3",
  "http://localhost:8000/api/v1/infrastructure?limit=3",
  "http://localhost:8000/api/v1/assets?limit=3",
  "http://localhost:8000/api/v1/map/features?limit=3"
)

foreach ($url in $endpoints) {
  $code = curl.exe -s -o NUL -w "%{http_code}" $url
  Write-Host "$code  $url"
}

Write-Host "`n=== FRONTEND BUILD ===" -ForegroundColor Cyan
Push-Location ".\frontend"
npm run build
$exit = $LASTEXITCODE
Pop-Location

if ($exit -ne 0) {
  Write-Host "Frontend build failed; running container not replaced." -ForegroundColor Yellow
  throw "GIS FRONTEND BUILD FAILED - SEND ONLY FIRST NEW ERROR"
}

Write-Host "`nFRONTEND BUILD PASS" -ForegroundColor Green

Write-Host "`n=== FRESH FRONTEND CONTAINER ===" -ForegroundColor Cyan
docker compose stop frontend
docker compose rm -f frontend
docker compose up -d --build --force-recreate --renew-anon-volumes frontend

Start-Sleep -Seconds 7

Write-Host "`n=== LIVE CHECK ===" -ForegroundColor Cyan
docker compose ps frontend

$front = curl.exe -s -o NUL -w "%{http_code}" "http://localhost:5173/gis"
$backend = curl.exe -s -o NUL -w "%{http_code}" "http://localhost:8000/docs"

Write-Host "GIS frontend : $front"
Write-Host "Backend docs : $backend"

Write-Host "`n=== IMPORTANT FIXES ===" -ForegroundColor Cyan
Write-Host "OpenStreetMap tiles - no CARTO API-key watermark"
Write-Host "Dynamic real asset types - no Bridge/Road/Building remapping"
Write-Host "Real PostGIS/API coordinates"
Write-Host "No fake healthy status for missing prediction data"
Write-Host "Missing values display N/A"
Write-Host "Search encoding fixed"
Write-Host "GIS endpoint fallback chain enabled"

if ($front -eq "200") {
  Write-Host "`n========================================" -ForegroundColor Green
  Write-Host "SIMRAS GIS REPAIR COMPLETE" -ForegroundColor Green
  Write-Host "========================================" -ForegroundColor Green
  Start-Process "http://localhost:5173/gis"
}
